import RawHtml from '../components/RawHtml';

const markup = "<div class=\"page\" data-page=\"about\">\n  <div class=\"wrap page-head\"><span class=\"kicker\">About Us</span><h1>The company behind <span class=\"o\">your growth.</span></h1><p>IntellioEra is a business growth company. We build the intelligent agents that run daily operations — so founders and teams can focus on the next stage, not the next report.</p></div>\n  <section class=\"sec\" id=\"about-story\">\n  <div class=\"wrap about\">\n    <div class=\"frame reveal\">\n      <img src=\"data:image/webp;base64,\" alt=\"Human and artificial intelligence, side by side\">\n      <div class=\"scan\"></div>\n      <span class=\"corner c1\"></span><span class=\"corner c2\"></span><span class=\"corner c3\"></span><span class=\"corner c4\"></span>\n      <div class=\"data\">HUMAN + AI<br>SYNCED<br>SECURE</div>\n      <div class=\"tag\"><i></i> Intelligence, on your side</div>\n    </div>\n    <div class=\"reveal\">\n      <span class=\"kicker\">Our story</span>\n      <h2>A business growth company, <span class=\"o\">powered by automation.</span></h2>\n      <p>IntellioEra builds business growth tools. We provide every kind of automation solution — from a single team that needs its daily targets managed, to enterprises that need hiring, field operations, marketing, finance, sales calls and content running on their own.</p>\n      <p>Our agents don't just report — they act. They assign, follow up, call, post, track and learn, and they hand work to one another so your business keeps moving even when your people rest.</p>\n      <div class=\"pill-row\"><span>Team management</span><span>Hiring &amp; HR</span><span>Field operations</span><span>Marketing &amp; sales</span><span>Voice &amp; calls</span><span>Finance</span><span>Content studio</span><span>Enterprise automation</span></div>\n      <div class=\"cta\"><a class=\"btn magnetic\" href=\"#/solutions\">See solutions by industry <svg viewBox=\"0 0 24 24\"><path d=\"M7 17L17 7M9 7h8v8\"/></svg></a></div>\n    </div>\n  </div>\n</section>\n  <section class=\"sec\" style=\"padding-top:10px\"><div class=\"wrap\">\n    <div class=\"about-deep reveal\">\n      <article class=\"about-panel\"><span class=\"n\">01 · OUR VISION</span><h3>Make intelligent growth available to every ambitious business.</h3><p>We see a future where a company's ability to grow is no longer limited by repetitive work, disconnected systems or delayed information. Every team should be able to operate with the speed, visibility and discipline of a world-class enterprise.</p></article>\n      <article class=\"about-panel\"><span class=\"n\">02 · OUR MISSION</span><h3>Turn everyday business work into connected, measurable automation.</h3><p>Our mission is to build practical AI agents that understand how a business actually runs. They connect decisions with action, keep people informed and continuously improve the systems that influence revenue, service, efficiency and control.</p></article>\n    </div>\n  </div></section>\n\n  <section class=\"sec\" style=\"padding-top:20px\"><div class=\"wrap\">\n    <div class=\"sec-head reveal\"><span class=\"kicker\">What we offer</span><h2>An intelligent layer for <span class=\"o\">every growth function.</span></h2><p>Choose one focused agent or connect the full ecosystem. Every tool can work independently, while the greatest value comes when information and actions flow between them.</p></div>\n    <div class=\"tool-spectrum reveal\">\n      <article class=\"tool-cap\"><i>01</i><h4>Leadership &amp; teams</h4><p>Targets, daily priorities, performance summaries, accountability and management follow-ups.</p></article>\n      <article class=\"tool-cap\"><i>02</i><h4>Sales &amp; conversations</h4><p>Intelligent calling, lead qualification, objection analysis, reminders and conversion workflows.</p></article>\n      <article class=\"tool-cap\"><i>03</i><h4>Marketing &amp; demand</h4><p>Audience discovery, campaign execution, outreach sequences and measurable pipeline generation.</p></article>\n      <article class=\"tool-cap\"><i>04</i><h4>Social &amp; content</h4><p>Strategy, calendars, posts, reels, publishing and performance-led content improvement.</p></article>\n      <article class=\"tool-cap\"><i>05</i><h4>Finance intelligence</h4><p>Cash-flow visibility, reconciliation, forecasts, risk signals and decision-ready financial briefs.</p></article>\n      <article class=\"tool-cap\"><i>06</i><h4>Field operations</h4><p>Live teams, visits, routes, proof of work, coverage insights and operational control.</p></article>\n      <article class=\"tool-cap\"><i>07</i><h4>People &amp; hiring</h4><p>Candidate screening, interview coordination, onboarding routines and workforce intelligence.</p></article>\n      <article class=\"tool-cap\"><i>08</i><h4>Custom automation</h4><p>Purpose-built agents, workflows, integrations and reporting shaped around unique operations.</p></article>\n    </div>\n  </div></section>\n\n  <section class=\"sec\" style=\"padding-top:20px\"><div class=\"wrap\">\n    <div class=\"sec-head reveal\"><span class=\"kicker\">How we create value</span><h2>From scattered work to a <span class=\"o\">self-improving system.</span></h2><p>We do more than place AI beside an existing process. We redesign how information moves, where action begins and how results are measured.</p></div>\n    <div class=\"operating-model reveal\">\n      <article class=\"model-step\"><h4>Understand</h4><p>We map people, systems, bottlenecks, targets and the decisions that drive the operation.</p></article>\n      <article class=\"model-step\"><h4>Connect</h4><p>Accounts, data and workflows come into one secure intelligence layer with clear permissions.</p></article>\n      <article class=\"model-step\"><h4>Automate</h4><p>Agents act across the routine, escalate exceptions and keep the right people in control.</p></article>\n      <article class=\"model-step\"><h4>Compound</h4><p>Every outcome becomes a new signal, helping the business move faster and improve over time.</p></article>\n    </div>\n  </div></section>\n  <section class=\"sec\" style=\"padding-top:0\"><div class=\"wrap\">\n    <div class=\"sec-head reveal\"><span class=\"kicker\">What we believe</span><h2>Growth should be <span class=\"o\">automatic.</span></h2></div>\n    <div class=\"vals reveal\">\n      <div class=\"val\"><i><svg viewBox=\"0 0 24 24\"><path d=\"M3 17l6-6 4 4 8-8M15 7h6v6\"/></svg></i><h4>Outcomes first</h4><p>Every agent exists to move a number that matters — revenue, speed, accuracy, cost. Activity without outcome is noise.</p></div>\n      <div class=\"val\"><i><svg viewBox=\"0 0 24 24\"><path d=\"M12 3l8 4v5c0 5-3.5 8-8 9-4.5-1-8-4-8-9V7z\"/><path d=\"M9 12l2 2 4-4\"/></svg></i><h4>Trust by design</h4><p>Encrypted, permissioned and auditable from day one. Your data runs your business — it never leaves your control.</p></div>\n      <div class=\"val\"><i><svg viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75\"/></svg></i><h4>People stay in charge</h4><p>Agents do the routine; people make the calls. IntellioEra makes your team faster and sharper, not smaller.</p></div>\n    </div>\n    <div class=\"strip reveal\" style=\"margin-top:22px\"><div><b>Global</b><small>Built without borders</small></div><div><b>Worldwide</b><small>Teams in every time zone</small></div><div><b>24/7</b><small>Agents on duty</small></div><div><b>1 week</b><small>Idea to live automation</small></div></div>\n    <div style=\"text-align:center;margin-top:40px;display:flex;gap:12px;justify-content:center;flex-wrap:wrap\"><a class=\"btn magnetic\" href=\"#/demo\">Book a Demo <svg viewBox=\"0 0 24 24\"><path d=\"M7 17L17 7M9 7h8v8\"/></svg></a><button class=\"btn ghost magnetic open-live\">Ask Live</button></div>\n  </div></section>\n</div>";

export default function AboutPage() {
  return <RawHtml html={markup} />;
}
